17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.LocalDate;
20	import java.util.Collection;
21	import java.util.List;
22	import java.util.Locale;
23	import java.util.Objects;
24	
25	import org.springframework.http.HttpHeaders;
26	import org.springframework.http.HttpStatus;
27	import org.springframework.http.ResponseEntity;
28	import org.springframework.samples.petclinic.mapper.OwnerMapper;
29	import org.springframework.samples.petclinic.mapper.PetMapper;
30	import org.springframework.samples.petclinic.mapper.VisitMapper;
31	import org.springframework.samples.petclinic.model.Owner;
32	import org.springframework.samples.petclinic.model.Pet;
33	import org.springframework.samples.petclinic.model.Visit;
34	import org.springframework.samples.petclinic.rest.api.OwnersApi;
35	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
36	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
37	import org.springframework.samples.petclinic.rest.dto.PetDto;
38	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
39	import org.springframework.samples.petclinic.rest.dto.VisitDto;
40	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
41	import org.springframework.samples.petclinic.service.ClinicService;
42	import org.springframework.security.access.prepost.PreAuthorize;
43	import org.springframework.web.bind.annotation.CrossOrigin;
44	import org.springframework.web.bind.annotation.RequestMapping;
45	import org.springframework.web.bind.annotation.RestController;
46	import org.springframework.web.util.UriComponentsBuilder;
47	
48	import jakarta.transaction.Transactional;
49	
50	/**
51	 * @author Vitaliy Fedoriv
52	 */
53	
54	@RestController
55	@CrossOrigin(exposedHeaders = "errors, content-type")
56	@RequestMapping("/api")
57	public class OwnerRestControllerV1 implements OwnersApi {
58	
59	    private final ClinicService clinicService;
60	
61	    private final OwnerMapper ownerMapper;
62	
63	    private final PetMapper petMapper;
64	
65	    private final VisitMapper visitMapper;
66	
67	    public OwnerRestControllerV1(ClinicService clinicService,
68	                                 OwnerMapper ownerMapper,
69	                                 PetMapper petMapper,
70	                                 VisitMapper visitMapper) {
71	        this.clinicService = clinicService;
72	        this.ownerMapper = ownerMapper;
73	        this.petMapper = petMapper;
74	        this.visitMapper = visitMapper;
75	    }
76	
77	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
78	    @Override
79	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
80	        Collection<Owner> owners;
81	        if (lastName != null) {
82	            owners = this.clinicService.findOwnerByLastName(lastName);
83	        } else {
84	            owners = this.clinicService.findAllOwners();
85	        }
86	        if (owners.isEmpty()) {
87	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
88	        }
89	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
90	    }
91	
92	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
93	    @Override
94	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
95	        Owner owner = this.clinicService.findOwnerById(ownerId);
96	        if (owner == null) {
97	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
98	        }
99	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
100	    }
101	
102	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
103	    @Override
104	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
105	        HttpHeaders headers = new HttpHeaders();
106	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
107	        owner.setTelephone(normalizeTelephone(owner.getTelephone()));
108	        if (isDuplicateOwner(owner) || isDuplicateEmail(owner)) {
109	            return new ResponseEntity<>(HttpStatus.CONFLICT);
110	        }
111	        if (owner.getRegistrationDate() == null) {
112	            owner.setRegistrationDate(LocalDate.now());
113	        }
114	        if (hasReachedDailyRegistrationLimit(owner.getRegistrationDate())) {
115	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
116	        }
117	        if (hasReachedCityCapacity(owner.getCity())) {
118	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
119	        }
120	        owner.setMembershipNumber(this.clinicService.findAllOwners().size() + 1);
121	        owner.setMembershipTier(determineMembershipTier(owner.getMembershipNumber()));
122	        owner.setCity(normalizeCity(owner.getCity()));
123	        owner.setCustomerCode(generateCustomerCode(owner.getCity()));
124	        this.clinicService.saveOwner(owner);
125	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
126	        headers.setLocation(UriComponentsBuilder.newInstance()
127	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
128	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
129	    }
130	
131	    /**
132	     * The maximum number of owners that may be registered on any single day.
133	     */
134	    private static final long MAX_OWNERS_PER_DAY = 20;
135	
136	    /**
137	     * Determines whether the number of owners already registered on the given date has reached the
138	     * daily registration limit. When 20 owners share the same registration date, no further owner may
139	     * be created for that day.
140	     */
141	    private boolean hasReachedDailyRegistrationLimit(LocalDate registrationDate) {
142	        long ownersRegisteredOnDate = this.clinicService.findAllOwners().stream()
143	            .filter(existing -> Objects.equals(existing.getRegistrationDate(), registrationDate))
144	            .count();
145	        return ownersRegisteredOnDate >= MAX_OWNERS_PER_DAY;
146	    }
147	
148	    /**
149	     * The maximum number of owners that may share a single city.
150	     */
151	    private static final long MAX_OWNERS_PER_CITY = 8;
152	
153	    /**
154	     * Determines whether the given city has already reached its capacity of owners. When a city
155	     * already contains 8 owners, no further owner may be created in that city. Cities are matched
156	     * ignoring letter case.
157	     */
158	    private boolean hasReachedCityCapacity(String city) {
159	        if (city == null) {
160	            return false;
161	        }
162	        long ownersInCity = this.clinicService.findAllOwners().stream()
163	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
164	            .count();
165	        return ownersInCity >= MAX_OWNERS_PER_CITY;
166	    }
167	
168	    /**
169	     * The number of owners that receive the founding membership tier. The first 100 owners ever
170	     * created are 'FOUNDING'; every owner created thereafter is 'STANDARD'.
171	     */
172	    private static final int FOUNDING_TIER_LIMIT = 100;
173	
174	    /**
175	     * Determines the membership tier for a newly created owner based on its sequential membership
176	     * number. Owners whose membership number is within the first {@value #FOUNDING_TIER_LIMIT} are
177	     * 'FOUNDING'; all later owners are 'STANDARD'.
178	     */
179	    private String determineMembershipTier(int membershipNumber) {
180	        return membershipNumber <= FOUNDING_TIER_LIMIT ? "FOUNDING" : "STANDARD";
181	    }
182	
183	    /**
184	     * Generates the customer code for a newly created owner. The code is formatted as
185	     * '&lt;UPPERCASE_CITY&gt;-&lt;NNNN&gt;' where NNNN is one more than the number of owners that
186	     * already exist in that city, zero-padded to four digits (for example 'LONDON-0007').
187	     * Cities are matched ignoring letter case.
188	     */
189	    private String generateCustomerCode(String city) {
190	        long ownersInCity = this.clinicService.findAllOwners().stream()
191	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
192	            .count();
193	        return String.format("%s-%04d", city.toUpperCase(Locale.ROOT), ownersInCity + 1);
194	    }
195	
196	    /**
197	     * Normalizes the city of a newly created owner. If an owner already exists in the same
198	     * city (matched ignoring letter case), that existing owner's exact spelling of the city is
199	     * reused so that all owners in a city share one canonical spelling. Otherwise the supplied
200	     * city is title-cased, capitalizing the first letter of each whitespace-separated word and
201	     * lowercasing the rest, so for example "new york" becomes "New York".
202	     */
203	    private String normalizeCity(String city) {
204	        if (city == null) {
205	            return null;
206	        }
207	        return this.clinicService.findAllOwners().stream()
208	            .map(Owner::getCity)
209	            .filter(existing -> existing != null && existing.equalsIgnoreCase(city))
210	            .findFirst()
211	            .orElseGet(() -> toTitleCase(city));
212	    }
213	
214	    /**
215	     * Title-cases the given value by capitalizing the first letter of each whitespace-separated
216	     * word and lowercasing the remaining letters, preserving the original whitespace: for example
217	     * "new  YORK" becomes "New  York".
218	     */
219	    private static String toTitleCase(String value) {
220	        StringBuilder result = new StringBuilder(value.length());
221	        boolean capitalizeNext = true;
222	        for (int i = 0; i < value.length(); i++) {
223	            char c = value.charAt(i);
224	            if (Character.isWhitespace(c)) {
225	                capitalizeNext = true;
226	                result.append(c);
227	            } else if (capitalizeNext) {
228	                result.append(Character.toTitleCase(c));
229	                capitalizeNext = false;
230	            } else {
231	                result.append(Character.toLowerCase(c));
232	            }
233	        }
234	        return result.toString();
235	    }
236	
237	    /**
238	     * Determines whether an owner already exists that uses the same telephone number
239	     * as the given one. Telephone numbers must be unique across all owners. The
240	     * comparison ignores letter case and any surrounding or repeated whitespace.
241	     */
242	    private boolean isDuplicateOwner(Owner owner) {
243	        String telephone = normalizeTelephone(owner.getTelephone());
244	        return this.clinicService.findAllOwners().stream()
245	            .anyMatch(existing -> Objects.equals(normalizeTelephone(existing.getTelephone()), telephone));
246	    }
247	
248	    /**
249	     * Normalizes a telephone number for storage and comparison by stripping spaces, dashes
250	     * and parentheses so that only digits remain: for example "(613) 555-0100" becomes
251	     * "6135550100". This lets differently punctuated forms of the same number be treated as
252	     * equal for the uniqueness check and stored in a single canonical form.
253	     */
254	    private static String normalizeTelephone(String telephone) {
255	        if (telephone == null) {
256	            return null;
257	        }
258	        return telephone.replaceAll("[\\s()-]", "");
259	    }
260	
261	    /**
262	     * Determines whether another owner already uses the same email address as the given one.
263	     * Email addresses, when supplied, must be unique across all owners. An owner without an
264	     * email address is never considered a duplicate. The comparison ignores letter case and
265	     * any surrounding or repeated whitespace.
266	     */
267	    private boolean isDuplicateEmail(Owner owner) {
268	        String email = normalize(owner.getEmail());
269	        if (email == null || email.isEmpty()) {
270	            return false;
271	        }
272	        return this.clinicService.findAllOwners().stream()
273	            .anyMatch(existing -> Objects.equals(normalize(existing.getEmail()), email));
274	    }
275	
276	    /**
277	     * Normalizes a user-supplied value for duplicate detection so that comparisons ignore
278	     * letter case and any surrounding or repeated whitespace: for example "  john   smith "
279	     * and "John Smith" normalize to the same key and so count as the same person.
280	     */
281	    private static String normalize(String value) {
282	        if (value == null) {
283	            return null;
284	        }
285	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
286	    }
287	
288	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
289	    @Override
290	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
291	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
292	        if (currentOwner == null) {
293	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
294	        }
295	        currentOwner.setAddress(ownerFieldsDto.getAddress());
296	        currentOwner.setCity(ownerFieldsDto.getCity());
