package org.springframework.samples.petclinic.rest.controller.v1;

import java.time.LocalDate;

import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;
import org.springframework.http.MediaType;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.model.Pet;
import org.springframework.samples.petclinic.model.PetType;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.repository.PetRepository;
import org.springframework.samples.petclinic.repository.PetTypeRepository;
import org.springframework.security.test.context.support.WithMockUser;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.transaction.annotation.Transactional;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.delete;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.put;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.header;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

/**
 * Integration tests for the /api/owners endpoints (including nested pets/visits), driven end-to-end
 * through the running application against real repositories.
 */
@SpringBootTest
@AutoConfigureMockMvc
@Transactional
class OwnerRestControllerV1Tests {

    @Autowired
    private MockMvc mvc;

    @Autowired
    private OwnerRepository ownerRepository;

    @Autowired
    private PetRepository petRepository;

    @Autowired
    private PetTypeRepository petTypeRepository;

    private Owner newOwner(String lastName) {
        Owner owner = new Owner();
        owner.setFirstName("George");
        owner.setLastName(lastName);
        owner.setAddress("110 W. Liberty St.");
        owner.setCity("Madison");
        owner.setTelephone("6085551023");
        ownerRepository.save(owner);
        return owner;
    }

    private PetType dogType() {
        PetType type = new PetType();
        type.setName("dog-" + System.nanoTime());
        petTypeRepository.save(type);
        return type;
    }

    @Test
    @WithMockUser(roles = "OWNER_ADMIN")
    void getOwnerSuccess() throws Exception {
        Owner owner = newOwner("Franklin-" + System.nanoTime());
        mvc.perform(get("/api/owners/" + owner.getId()).accept(MediaType.APPLICATION_JSON))
            .andExpect(status().isOk())
            .andExpect(jsonPath("$.id").value(owner.getId()))
            .andExpect(jsonPath("$.firstName").value("George"));
    }

    @Test
    @WithMockUser(roles = "OWNER_ADMIN")
    void getOwnerNotFound() throws Exception {
        mvc.perform(get("/api/owners/999999").accept(MediaType.APPLICATION_JSON))
            .andExpect(status().isNotFound());
    }

    @Test
    @WithMockUser(roles = "OWNER_ADMIN")
    void listOwnersByLastNameSuccess() throws Exception {
        String uniqueLastName = "Davis-" + System.nanoTime();
        Owner owner = newOwner(uniqueLastName);
        mvc.perform(get("/api/owners?lastName=" + uniqueLastName).accept(MediaType.APPLICATION_JSON))
            .andExpect(status().isOk())
            .andExpect(jsonPath("$.[0].id").value(owner.getId()))
            .andExpect(jsonPath("$.[0].lastName").value(uniqueLastName));
    }

    @Test
    @WithMockUser(roles = "OWNER_ADMIN")
    void listOwnersByLastNameNotFound() throws Exception {
        mvc.perform(get("/api/owners?lastName=NoSuchOwnerLastName").accept(MediaType.APPLICATION_JSON))
            .andExpect(status().isNotFound());
    }

    @Test
    @WithMockUser(roles = "OWNER_ADMIN")
    void createOwnerSuccess() throws Exception {
        String body = """
            {"firstName":"George","lastName":"Newman","address":"1 New St.","city":"Springfield","telephone":"6085559999"}
            """;
        mvc.perform(post("/api/owners").content(body)
                .accept(MediaType.APPLICATION_JSON).contentType(MediaType.APPLICATION_JSON))
            .andExpect(status().isCreated())
            .andExpect(header().string("Location", org.hamcrest.Matchers.containsString("/api/owners/")))
            .andExpect(jsonPath("$.firstName").value("George"))
            .andExpect(jsonPath("$.displayName").value("Newman, George"));
    }

    @Test
    @WithMockUser(roles = "OWNER_ADMIN")
    void createOwnerAssignsCustomerCodeForNewCity() throws Exception {
        String city = "Metropolis" + System.nanoTime();
        String body = """
            {"firstName":"Clark","lastName":"Kent","address":"1 Daily St.","city":"%s","telephone":"6085557777"}
            """.formatted(city);
        mvc.perform(post("/api/owners").content(body)
                .accept(MediaType.APPLICATION_JSON).contentType(MediaType.APPLICATION_JSON))
            .andExpect(status().isCreated())
            .andExpect(jsonPath("$.customerCode").value(city.toUpperCase() + "-0001"));
    }

    @Test
    @WithMockUser(roles = "OWNER_ADMIN")
    void createOwnerIncrementsCustomerCodeWithinSameCity() throws Exception {
        String city = "Gotham" + System.nanoTime();
        String first = """
            {"firstName":"Bruce","lastName":"Wayne","address":"1 Manor Rd.","city":"%s","telephone":"6085557001"}
            """.formatted(city);
        mvc.perform(post("/api/owners").content(first)
                .accept(MediaType.APPLICATION_JSON).contentType(MediaType.APPLICATION_JSON))
            .andExpect(status().isCreated())
            .andExpect(jsonPath("$.customerCode").value(city.toUpperCase() + "-0001"));

        String second = """
            {"firstName":"Selina","lastName":"Kyle","address":"2 Alley Rd.","city":"%s","telephone":"6085557002"}
            """.formatted(city);
        mvc.perform(post("/api/owners").content(second)
                .accept(MediaType.APPLICATION_JSON).contentType(MediaType.APPLICATION_JSON))
            .andExpect(status().isCreated())
            .andExpect(jsonPath("$.customerCode").value(city.toUpperCase() + "-0002"));
    }

    @Test
    @WithMockUser(roles = "OWNER_ADMIN")
    void createOwnerTitleCasesCityForNewCity() throws Exception {
        String suffix = String.valueOf(System.nanoTime());
        String body = """
            {"firstName":"Ariel","lastName":"Waters","address":"1 Coral Rd.","city":"north %s","telephone":"6085556001"}
            """.formatted(suffix);
        mvc.perform(post("/api/owners").content(body)
                .accept(MediaType.APPLICATION_JSON).contentType(MediaType.APPLICATION_JSON))
            .andExpect(status().isCreated())
            .andExpect(jsonPath("$.city").value("North " + suffix));
    }

    @Test
    @WithMockUser(roles = "OWNER_ADMIN")
    void createOwnerReusesExistingCitySpelling() throws Exception {
        String city = "Rivertown" + System.nanoTime();
        String first = """
            {"firstName":"Bruce","lastName":"Rivers","address":"1 First Rd.","city":"%s","telephone":"6085556101"}
            """.formatted(city);
        mvc.perform(post("/api/owners").content(first)
                .accept(MediaType.APPLICATION_JSON).contentType(MediaType.APPLICATION_JSON))
            .andExpect(status().isCreated())
            .andExpect(jsonPath("$.city").value(city));

        String second = """
            {"firstName":"Clark","lastName":"Streams","address":"2 Second Rd.","city":"%s","telephone":"6085556102"}
            """.formatted(city.toUpperCase());
        mvc.perform(post("/api/owners").content(second)
                .accept(MediaType.APPLICATION_JSON).contentType(MediaType.APPLICATION_JSON))
            .andExpect(status().isCreated())
            .andExpect(jsonPath("$.city").value(city));
    }

    @Test
    @WithMockUser(roles = "OWNER_ADMIN")
    void createOwnerDuplicateLastNameAndTelephoneReturnsConflict() throws Exception {
        String lastName = "Conflictus";
        newOwner(lastName); // telephone 6085551023
        String body = """
            {"firstName":"Different","lastName":"%s","address":"999 Other St.","city":"Elsewhere","telephone":"6085551023"}
            """.formatted(lastName);
        mvc.perform(post("/api/owners").content(body)
                .accept(MediaType.APPLICATION_JSON).contentType(MediaType.APPLICATION_JSON))
            .andExpect(status().isConflict());
    }

    @Test
    @WithMockUser(roles = "OWNER_ADMIN")
    void createOwnerDuplicateTelephoneDifferentLastNameReturnsConflict() throws Exception {
        newOwner("Existingus"); // telephone 6085551023
        String body = """
            {"firstName":"George","lastName":"Differentus","address":"999 Other St.","city":"Elsewhere","telephone":"6085551023"}
            """;
        mvc.perform(post("/api/owners").content(body)
                .accept(MediaType.APPLICATION_JSON).contentType(MediaType.APPLICATION_JSON))
            .andExpect(status().isConflict());
    }

    @Test
    @WithMockUser(roles = "OWNER_ADMIN")
    void createOwnerSameLastNameDifferentTelephoneSucceeds() throws Exception {
        String lastName = "Samenamius";
        newOwner(lastName); // telephone 6085551023
        String body = """
            {"firstName":"George","lastName":"%s","address":"110 W. Liberty St.","city":"Madison","telephone":"6085550000"}
            """.formatted(lastName);
        mvc.perform(post("/api/owners").content(body)
                .accept(MediaType.APPLICATION_JSON).contentType(MediaType.APPLICATION_JSON))
            .andExpect(status().isCreated());
    }

    @Test
    @WithMockUser(roles = "OWNER_ADMIN")
    void createOwnerReturnsZeroNamesakeCountForUniqueLastName() throws Exception {
        String lastName = "Solitarius" + System.nanoTime();
        String body = """
            {"firstName":"George","lastName":"%s","address":"1 New St.","city":"Springfield","telephone":"6085552301"}
            """.formatted(lastName);
        mvc.perform(post("/api/owners").content(body)
                .accept(MediaType.APPLICATION_JSON).contentType(MediaType.APPLICATION_JSON))
            .andExpect(status().isCreated())
            .andExpect(jsonPath("$.namesakeCount").value(0));
    }

    @Test
    @WithMockUser(roles = "OWNER_ADMIN")
    void createOwnerCountsExistingOwnersWithSameLastName() throws Exception {
        String lastName = "Namesakius" + System.nanoTime();
        newOwner(lastName); // one existing owner with this last name

        String body = """
            {"firstName":"George","lastName":"%s","address":"1 New St.","city":"Springfield","telephone":"6085552302"}
            """.formatted(lastName);
        mvc.perform(post("/api/owners").content(body)
                .accept(MediaType.APPLICATION_JSON).contentType(MediaType.APPLICATION_JSON))
            .andExpect(status().isCreated())
            .andExpect(jsonPath("$.namesakeCount").value(1));

        String third = """
            {"firstName":"Second","lastName":"%s","address":"2 New St.","city":"Springfield","telephone":"6085552303"}
            """.formatted(lastName);
        mvc.perform(post("/api/owners").content(third)
                .accept(MediaType.APPLICATION_JSON).contentType(MediaType.APPLICATION_JSON))
            .andExpect(status().isCreated())
            .andExpect(jsonPath("$.namesakeCount").value(2));
    }

    @Test
    @WithMockUser(roles = "OWNER_ADMIN")
    void createOwnerWithEmailStoresAndReturnsEmail() throws Exception {
        String body = """
            {"firstName":"George","lastName":"Emailer","address":"1 New St.","city":"Springfield","telephone":"6085558001","email":"george.emailer@example.com"}
            """;
        mvc.perform(post("/api/owners").content(body)
                .accept(MediaType.APPLICATION_JSON).contentType(MediaType.APPLICATION_JSON))
            .andExpect(status().isCreated())
            .andExpect(jsonPath("$.email").value("george.emailer@example.com"));
    }

    @Test
    @WithMockUser(roles = "OWNER_ADMIN")
    void createOwnerDuplicateEmailReturnsConflict() throws Exception {
        String first = """
            {"firstName":"George","lastName":"FirstEmail","address":"1 New St.","city":"Springfield","telephone":"6085558002","email":"dup@example.com"}
            """;
        mvc.perform(post("/api/owners").content(first)
                .accept(MediaType.APPLICATION_JSON).contentType(MediaType.APPLICATION_JSON))
            .andExpect(status().isCreated());

        String second = """
            {"firstName":"Sarah","lastName":"SecondEmail","address":"2 New St.","city":"Springfield","telephone":"6085558003","email":"dup@example.com"}
            """;
        mvc.perform(post("/api/owners").content(second)
                .accept(MediaType.APPLICATION_JSON).contentType(MediaType.APPLICATION_JSON))
            .andExpect(status().isConflict());
    }

